// @ts-check
import { defineConfig } from 'astro/config';
import starlight from '@astrojs/starlight';
import starlightLinksValidator from 'starlight-links-validator';

// docs.bellman.sh. Pages are Markdown under src/content/docs/. reference/tools/ and
// reference/bridge-tools.md are generated by `npm run docs:gen` at the repo root.
export default defineConfig({
  site: 'https://docs.bellman.sh',
  // Straight quotes, as the tools write them: a reader copies "html" or "surface" from a tool page.
  markdown: { smartypants: false },
  integrations: [
    starlight({
      title: 'Bellman',
      // A broken internal link fails `astro build`, so it fails the pull request that made it.
      plugins: [starlightLinksValidator()],
      // A group lists its directory's pages by their `sidebar.order`. A slug named here must
      // exist or the build fails, so an explicit entry lands in the same change as its page.
      sidebar: [
        { label: 'Start', items: ['index', { autogenerate: { directory: 'start' } }] },
        { label: 'Guides', items: [{ autogenerate: { directory: 'guides' } }] },
        { label: 'Concepts', items: [{ autogenerate: { directory: 'concepts' } }] },
        {
          label: 'Reference',
          items: [
            { label: 'Tools', items: [{ autogenerate: { directory: 'reference/tools' } }] },
            'reference/bridge-tools',
            'reference/bellman-command',
          ],
        },
        { label: 'Help', items: [{ autogenerate: { directory: 'help' } }] },
      ],
    }),
  ],
});
